{"packet_id":"D026-01","doc_id":"D026","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California application screening fee cap","requirement":"A landlord or agent may charge an application screening fee only up to $30 per applicant, never more than actual out-of-pocket costs, must give an itemized receipt, and must refund unused or improperly collected fees within seven days.","key_value":"$30 per applicant, CPI-adjustable","coverage_conditions":"Any landlord or agent renting residential property; applies to applicants, guarantors and cosignors. \u201clandlord\u201d means an owner of residential rental property.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential rental applicants, guarantors and cosignors"},"exemptions":"No fee when no rental unit is available or will be available; no refund required of an applicant denied after consideration because they fail the screening criteria; section does not preempt federal or state housing assistance program rules.","penalty":null,"effective_date":"2026-01-01","citation":"Cal. Civ. Code § 1950.6","quoted_span":"In no case shall the amount of the application screening fee charged by the landlord or their agent be greater than thirty dollars ($30) per applicant. The thirty dollar ($30) application screening fee may be adjusted annually by the landlord or their agent commensurate with an increase in the Consumer Price Index, beginning on January 1, 1998.","interaction":"Section is not intended to preempt federal or state housing assistance program rules governing collection of deposits and fees.","confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D026-01","doc_id":"D026","jurisdiction":"CA","category":"screening_restrictions","lifecycle":"enacted","title":"California application screening order and written criteria rule","requirement":"A landlord or agent charging an application screening fee must give the applicant the screening criteria in writing with the application and consider completed applications in the order received, approving the first applicant who meets the criteria.","key_value":null,"coverage_conditions":"Any landlord or agent renting residential property; applies to applicants, guarantors and cosignors. \u201clandlord\u201d means an owner of residential rental property.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential rental applicants, guarantors and cosignors"},"exemptions":null,"penalty":null,"effective_date":"2026-01-01","citation":"Cal. Civ. Code § 1950.6","quoted_span":"Completed applications are considered, as provided for in the landlord\u2019s established screening criteria, in the order in which the completed applications were received. The landlord\u2019s screening criteria shall be provided to the applicant in writing together with the application form.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
